#include <linux/fb.h>
#include <linux/mm.h>
#include <linux/mutex.h>

int fb_mmap(struct file *file, struct vm_area_struct *vma)
{
    struct fb_info *info = file->private_data;
    int ret = -EINVAL;

    if (!info || !vma)
        return ret;

    mutex_lock(&info->mmio_lock);

    if (info->fbops->mmap) {
        ret = info->fbops->mmap(info, vma);
        mutex_unlock(&info->mmio_lock);
        return ret;
    }

    {
        unsigned long start = vma->vm_start;
        unsigned long size = vma->vm_end - vma->vm_start;
        unsigned long offset = vma->vm_pgoff << PAGE_SHIFT;
        unsigned long page;

        if (offset < info->fix.smem_len)
            page = info->fix.smem_start + offset;
        else {
            offset -= info->fix.smem_len;
            page = info->var.accel.len + offset;
        }

        vma->vm_flags |= VM_IO | VM_PFNMAP | VM_DONTEXPAND | VM_DONTDUMP;
        vma->vm_page_prot = pgprot_noncached(vma->vm_page_prot);

        ret = io_remap_pfn_range(vma, start, page >> PAGE_SHIFT,
                                 size, vma->vm_page_prot);
    }

    mutex_unlock(&info->mmio_lock);
    return ret;
}

int my_fb_mmap(struct file *file, struct vm_area_struct *vma)
{
    struct fb_info *info = file->private_data;
    int ret = 0;

    if (!info || !info->var.xres)
        return -EINVAL;

    mutex_lock(&info->mm_lock);

    if (info->fbops->mmap) {
        ret = info->fbops->mmap(info, vma);
        mutex_unlock(&info->mm_lock);
        return ret;
    }

    {
        unsigned long start, length;
        struct page *page;

        if (vma->vm_pgoff == 0) {
            start = info->fix.smem_start;
            length = info->fix.smem_len;
            page = info->screen_base ?
                virt_to_page(info->screen_base) : NULL;
        } else {
            start = info->fix.mmio_start;
            length = info->fix.mmio_len;
            page = info->pseudo_palette ? virt_to_page(info->pseudo_palette) : NULL;
        }

        if (!page)
            return -EINVAL;

        vma->vm_page_prot = pgprot_noncached(vma->vm_page_prot);
        vma->vm_flags |= VM_IO;

        ret = remap_pfn_range(vma, vma->vm_start, start >> PAGE_SHIFT,
                              length, vma->vm_page_prot);
    }

    mutex_unlock(&info->mm_lock);

    return ret;
}

int my_framebuffer_mmap(struct file *file, struct vm_area_struct *vma) {
    struct fb_info *info = file->private_data;
    int ret = 0;

    if (!info || !info->fbops)
        return -EINVAL;

    mutex_lock(&info->mmio_lock);

    if (info->fbops->fb_mmap) {
        ret = info->fbops->fb_mmap(info, vma);
        mutex_unlock(&info->mmio_lock);
        return ret;
    }

    {
        unsigned long start = vma->vm_start;
        unsigned long size = vma->vm_end - vma->vm_start;
        unsigned long page_offset = vma->vm_pgoff;

        if (page_offset < info->var.xres_virtual * info->var.bits_per_pixel / 8) {
            start = info->fix.smem_start;
            start += page_offset;
            size = min(size, info->fix.smem_len - page_offset);
        } else {
            start = info->var.accel.len;
            start += page_offset - info->var.xres_virtual * info->var.bits_per_pixel / 8;
            size = min(size, info->var.accel.len - page_offset + info->var.xres_virtual * info->var.bits_per_pixel / 8);
        }

        if (start > info->fix.smem_start + info->fix.smem_len)
            return -EINVAL;

        if (vma->vm_flags & VM_WRITE)
            vma->vm_flags &= ~VM_WRITE;

        vma->vm_flags |= VM_IO | VM_PFNMAP;
        vma->vm_page_prot = pgprot_noncached(vma->vm_page_prot);
        if (remap_pfn_range(vma, start, start >> PAGE_SHIFT, size, vma->vm_page_prot))
            ret = -EAGAIN;
    }

    mutex_unlock(&info->mmio_lock);
    return ret;
}
